    public static final List<String> SKIP_REASONS=List.of("writer_registers_missing","writer_register_arguments_mismatch","writer_event_clock_thread_invalid","game_state_date_unavailable_or_mismatch","source_army_identity_unreadable_or_unstable","native_army_registry_mismatch","public_unit_registry_mismatch","public_native_bidirectional_mismatch","writer_identity_mismatch","writer_registry_mismatch","army_roster_unreadable_or_unstable","writer_not_unique_in_actual_army_array","physical_association_incomplete","physical_capture_incomplete","natural_sampling_changed_or_disabled","actual4_source_unqualified");
