    private static void checkComplete(Map<DirectU64,Optional<BigInteger>> u64,Map<DirectU32,Optional<Long>> u32,Map<DirectI32,Optional<Integer>> i32,Map<DirectBool,Optional<Boolean>> b,Token event,Optional<BigInteger> date,List<Association> associations){
        require(u32.get(DirectU32.CAPTURE_FAILURE_FLAGS).orElseThrow()==0,"complete direct source has failures");
        for(DirectBool key:List.of(DirectBool.NATURAL_SAMPLING_ENABLED,DirectBool.ACTUAL4_SOURCE_QUALIFIED,DirectBool.RECEIVER_IDENTITY_MATCHES,DirectBool.WRITER_IDENTITY_MATCHES,DirectBool.NATIVE_ARMY_REGISTRY_MATCHES,DirectBool.PUBLIC_UNIT_REGISTRY_MATCHES,DirectBool.PUBLIC_NATIVE_BIDIRECTIONAL_MATCHES,DirectBool.WRITER_REGISTRY_MATCHES,DirectBool.ACTUAL_ARRAY_CONTAINS_WRITER,DirectBool.PHYSICAL_ASSOCIATION_COMPLETE,DirectBool.PHYSICAL_CAPTURE_COMPLETE))require(b.get(key).orElseThrow(),"complete direct native guard false");
        for(DirectU64 key:List.of(DirectU64.WRITER_INVOCATION_TOKEN,DirectU64.WRITER_RECEIVER_IDENTITY,DirectU64.SOURCE_CARMY_IDENTITY,DirectU64.CURRENT_GAME_STATE_IDENTITY,DirectU64.PUBLIC_UNIT_IDENTITY,DirectU64.NATURAL_SAMPLING_EPOCH,DirectU64.NATIVE_ARMY_REGISTRY_IDENTITY,DirectU64.PUBLIC_UNIT_REGISTRY_IDENTITY,DirectU64.WRITER_REGISTRY_IDENTITY))require(u64.get(key).orElseThrow().signum()>0,"complete direct native identity absent");
        for(DirectI32 key:List.of(DirectI32.ARMY_ID,DirectI32.NATIVE_CARMY_ID,DirectI32.WRITER_FULL_REGIMENT_ID))require(i32.get(key).filter(v->v!=-1).isPresent(),"complete direct fullID absent");
        require(u64.get(DirectU64.NATIVE_ARMY_REGISTRY_IDENTITY).equals(u64.get(DirectU64.SOURCE_CARMY_IDENTITY))&&u64.get(DirectU64.PUBLIC_UNIT_REGISTRY_IDENTITY).equals(u64.get(DirectU64.PUBLIC_UNIT_IDENTITY))&&u64.get(DirectU64.WRITER_REGISTRY_IDENTITY).equals(u64.get(DirectU64.WRITER_RECEIVER_IDENTITY)),"direct registry identity differs");
        require(u32.get(DirectU32.WRITER_THREAD_ID).orElseThrow()>0&&event.clockIdentity().signum()>0&&event.sequence().signum()>0&&event.threadId().equals(u32.get(DirectU32.WRITER_THREAD_ID))&&date.isPresent(),"direct writer clock/thread/date absent");
        int count=i32.get(DirectI32.ARMY_ROSTER_COUNT).orElse(-1),occurrence=i32.get(DirectI32.ARMY_ROSTER_OCCURRENCE).orElse(-1);require(occurrence>=0&&occurrence<count&&count<=65536&&!associations.isEmpty(),"direct actual roster/DATA absent");
        Map<Integer,BigInteger> slots=new HashMap<>();for(int index=0;index<associations.size();index++){Association a=associations.get(index);int data=a.signed32().get(AssociationI32.DATA_RECORD_INDEX).orElseThrow(),persistent=a.signed32().get(AssociationI32.PERSISTENT_REGIMENT_ID).orElseThrow(),chunk=a.signed32().get(AssociationI32.DATA_CHUNK_ORDINAL).orElseThrow(),slot=a.signed32().get(AssociationI32.PHYSICAL_SLOT_INDEX).orElseThrow();BigInteger registry=a.unsigned64().get(AssociationU64.PERSISTENT_REGISTRY_IDENTITY).orElseThrow(),selected=a.unsigned64().get(AssociationU64.SELECTED_PHYSICAL_IDENTITY).orElseThrow(),expected=a.unsigned64().get(AssociationU64.EXPECTED_PHYSICAL_IDENTITY).orElseThrow();require(data==index&&persistent!=-1&&chunk>=0&&chunk<=6&&slot>=0&&a.registryMatches()&&a.physicalIdentityMatches()&&registry.signum()>0&&selected.signum()>0&&selected.equals(expected)&&selected.equals(registry.add(BigInteger.valueOf(0x18L+chunk*0x24L))),"direct physical association differs");require(a.signed32().get(AssociationI32.PHYSICAL_PERSISTENT_REGIMENT_ID).filter(v->v==persistent).isPresent()&&a.signed32().get(AssociationI32.PHYSICAL_OWN_ORDINAL).filter(v->v==chunk).isPresent()&&a.signed32().get(AssociationI32.PHYSICAL_ARMY_REGIMENT_ID).equals(i32.get(DirectI32.WRITER_FULL_REGIMENT_ID)),"direct physical ownership triple differs");BigInteger before=slots.putIfAbsent(slot,selected);require(before==null||before.equals(selected),"physical alias slot differs");}require(new HashSet<>(slots.values()).size()==slots.size(),"distinct physical slots share an identity");
    }
